<?php namespace App\Http\Resources; use Illuminate\Http\Request; use Illuminate\Http\Resources\Json\JsonResource; class EventResource extends JsonResource {public function toArray(Request $r):array{return ['id'=>$this->id,'title'=>$this->title,'description'=>$this->description,'city'=>$this->city,'category'=>$this->category,'starts_at'=>$this->starts_at,'status'=>$this->status->value,'organizer'=>['id'=>$this->organizer?->id,'name'=>$this->organizer?->name],'venue'=>$this->whenLoaded('venue'),'ticket_categories'=>$this->whenLoaded('ticketTypes',fn()=>$this->ticketTypes->map(fn($x)=>['id'=>$x->id,'name'=>$x->name,'type'=>$x->type->value,'price'=>$x->price,'remaining'=>max(0,$x->quantity-$x->sold)]))];}}
